\section{Introduction}

Let $\mathbb{Z}$ denote the integers. A finite set $S \subset \mathbb{Z}$ is a
\textbf{Sidon set} if for all $a, b, c, d \in S$,
\[ a + b = c + d \implies \{a, b\} = \{c, d\}. \]
Equivalently (Proposition~\ref{prop:sumdiff} below), all pairwise differences
of distinct elements are distinct. Such sets, introduced by Simon Sidon in the
study of Fourier series, are also called $B_2$ sets and are a cornerstone of
additive combinatorics.

The natural extremal quantity is
\[ F(N) := \max\{ |S| : S \subseteq \{1, 2, \dots, N\},\ S \text{ is Sidon}\}. \]
The Erd\H{o}s--Tur\'an theory gives $F(N) = N^{1/2}(1 + o(1))$ with the refined
upper bound
\begin{equation}
F(N) \le N^{1/2} + \gamma\, N^{1/4} + O(1), \label{eq:et}
\end{equation}
and a substantial line of work --- culminating in vector-valued
convolution-kernel optimizations --- is devoted to the optimal constant
$\gamma$.

This paper isolates the elementary engine behind \eqref{eq:et}: the
\textbf{difference-set method}. We prove the leading-order upper bound
rigorously, establish an explicit unbounded family from first principles, and
map the terrain in which the finer constant $\gamma$ is contested.

\section{Definitions and elementary equivalences}

\begin{definition}[Sidon set]
A finite set $S \subset \mathbb{Z}$ is a \emph{Sidon set} if whenever
$a, b, c, d \in S$ satisfy $a + b = c + d$, then $\{a, b\} = \{c, d\}$ as
multisets.
\end{definition}

\begin{proposition}[Sums vs.\ differences]\label{prop:sumdiff}
A finite set $S$ is Sidon if and only if all pairwise differences $a - b$ with
$a, b \in S$, $a \ne b$, are distinct.
\end{proposition}

\begin{proof}
The identity $a - b = c - d \iff a + d = c + b$ converts a repeated difference
into a repeated sum and back. If $S$ is Sidon and $a - b = c - d$, then $a + d
= c + b$ forces $\{a, d\} = \{c, b\}$; since $a \ne b$ and $c \ne d$ this
yields $a = c$, $b = d$. Conversely a repeated sum with $\{a,b\} \ne \{c,d\}$
produces a repeated difference by the same rearrangement.
\end{proof}

\begin{definition}[Extremal function]
$F(N) = \max\{|S| : S \subseteq \{1,\dots,N\},\ S \text{ Sidon}\}$.
\end{definition}

\section{The difference-set method and the square-root ceiling}

Fix a Sidon set $S \subseteq \{1, \dots, N\}$ with $|S| = m$, and let
$\mathrm{OffDiag}(S) = \{(a,b) \in S \times S : a \ne b\}$, of cardinality
$m(m-1)$.

\begin{theorem}[Difference injectivity]\label{thm:inj}
The map $\delta : \mathrm{OffDiag}(S) \to \mathbb{Z}$, $\delta(a,b) = a - b$,
is injective.
\end{theorem}

\begin{proof}
Suppose $a - b = c - d$ with $a \ne b$ and $c \ne d$. Then $a + d = c + b$, and
since $S$ is Sidon, $\{a, d\} = \{c, b\}$. The constraints $a \ne b$ and $c \ne
d$ force $a = c$ and $b = d$, so $(a,b) = (c,d)$.
\end{proof}

\begin{lemma}[Difference window]\label{lem:window}
For $(a,b) \in \mathrm{OffDiag}(S)$ with $S \subseteq \{1, \dots, N\}$, the
value $a - b$ is a nonzero integer with $|a - b| \le N - 1$. Hence $\delta$
takes values in a set of exactly $2(N-1)$ elements.
\end{lemma}

\begin{proof}
Both $a, b \in \{1, \dots, N\}$, so $a - b \in \{-(N-1), \dots, N-1\}$; it is
nonzero because $a \ne b$.
\end{proof}

\begin{theorem}[Quantitative counting bound]\label{thm:count}
If $S \subseteq \{1, \dots, N\}$ is Sidon then $|S|\,(|S| - 1) \le 2(N - 1)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:inj} the map $\delta$ is injective, so its domain (of size
$|S|(|S|-1)$) is no larger than its codomain (of size $2(N-1)$ by
Lemma~\ref{lem:window}).
\end{proof}

\begin{theorem}[Square-root ceiling]\label{thm:sqrt}
For all $N \ge 1$, $\;F(N) \le \sqrt{2N} + 1 = \sqrt{2}\,N^{1/2} + 1$.
\end{theorem}

\begin{proof}
Let $m = |S|$ for an extremal Sidon set. Theorem~\ref{thm:count} gives $m^2 - m
\le 2N - 2$. Solving the quadratic and keeping the positive root,
\[ m \le \frac{1 + \sqrt{8N - 7}}{2} \le \frac{1}{2} + \sqrt{2N} \le \sqrt{2N}
+ 1. \qedhere \]
\end{proof}

\section{An explicit unbounded family: the powers of two}

\begin{definition}
For $k \in \mathbb{N}$, let $P_k = \{2^0, 2^1, \dots, 2^{k-1}\}$, the image of
$\{0, \dots, k-1\}$ under $i \mapsto 2^i$. Since this map is injective,
$|P_k| = k$.
\end{definition}

\begin{theorem}[Two-power sum uniqueness]\label{thm:twopow}
For natural numbers $a, b, c, d$, $\;2^a + 2^b = 2^c + 2^d \implies a = c
\text{ or } a = d$.
\end{theorem}

\begin{proof}
We show the stronger $\{a, b\} = \{c, d\}$. By symmetry assume $a \le b$ and
$c \le d$, and factor:
\[ 2^a\bigl(1 + 2^{b-a}\bigr) = 2^c\bigl(1 + 2^{d-c}\bigr). \]
Let $v_2$ be the $2$-adic valuation. The factor $1 + 2^{b-a}$ is odd when $b >
a$ and equals $2$ when $b = a$ (similarly for $1 + 2^{d-c}$). Comparing $v_2$
of both sides across the cases forces $a = c$; cancellation then gives $1 +
2^{b-a} = 1 + 2^{d-c}$, hence $b = d$. The carry case $b = a$ (where $2^a +
2^a = 2^{a+1}$) cannot match a distinct pair $c < d$ because $1 + 2^{d-c}$ is
odd and exceeds $1$.
\end{proof}

\begin{theorem}[Powers of two are Sidon]\label{thm:pksidon}
For every $k$, the set $P_k$ is a Sidon set.
\end{theorem}

\begin{proof}
If $2^a + 2^b = 2^c + 2^d$ with all exponents in $\{0, \dots, k-1\}$, then
Theorem~\ref{thm:twopow} yields $\{a, b\} = \{c, d\}$, so the corresponding
elements coincide as multisets.
\end{proof}

\begin{theorem}[Unboundedness]\label{thm:unbounded}
For every $k \in \mathbb{N}$ there exists a Sidon set $S \subset \mathbb{Z}$
with $|S| = k$; hence $F(N)$ is unbounded.
\end{theorem}

\begin{proof}
Take $S = P_k$, Sidon by Theorem~\ref{thm:pksidon} with $|P_k| = k$.
\end{proof}

\begin{remark}
The family $P_k$ is cheap but wasteful: fitting $k$ powers needs a window of
length $2^{k-1}$, so $P_k$ only witnesses $F(N) \ge \log_2 N + 1$. Matching the
true $\sqrt{N}$ order from below requires the constructions of
Section~\ref{sec:landscape}.
\end{remark}

\section{The finer landscape: constant chasing and convolution kernels}
\label{sec:landscape}

The elementary bound of Theorem~\ref{thm:sqrt} has leading constant $\sqrt{2}
\approx 1.414$, whereas the true leading constant of $F(N)/N^{1/2}$ is $1$. The
gap is structural: the difference count sees each distance once and cannot
distinguish a Sidon set from a set whose differences merely spread evenly.
Recovering the sharp constant requires averaging local density over sliding
windows, where overlap structure carries the decisive information.

\subsection{Matching lower bounds}
For a prime $p$, the quadratic family
\[ Q_p = \{ 2p\,i + (i^2 \bmod p) : 0 \le i < p \} \]
is a Sidon set inside $\{1, \dots, 2p^2\}$, giving $F(N) \ge (1 - o(1))
N^{1/2}$. Squaring linearizes distinctness: two pairs collide only if a
symmetric quadratic congruence has a nontrivial solution, which the modular
structure forbids. The Singer and Erd\H{o}s--Tur\'an constructions achieve the
same order with sharp leading constant.

\subsection{The Erd\H{o}s--Tur\'an refinement}
Combining sharp constructions with refined counting yields \eqref{eq:et}; the
leading term is settled and the coefficient $\gamma$ of the $N^{1/4}$
correction is the object of contention.

\subsection{The vector-valued convolution-kernel programme}
The modern approach convolves the difference distribution against a
\emph{kernel} and averages, turning the count into an inner product between the
kernel and the autocorrelation of the indicator of $S$. Feasible kernels
satisfy convolution inequalities; the bound is a weighted average of them.
Vector-valued kernels with optimized weights reduce the search to a
finite-dimensional linear program whose conjectured optimum is
\[ \gamma_0 \approx 0.94601, \]
realized as the saddle point of a duality between the kernel inequalities and
the certifying weighting. This averaging-of-local-operators motif is exactly
the design principle behind convolutional filters in signal processing and
machine learning.

\section{Algorithms}

\textbf{Algorithm A (Sidon verification).} Compute all pairwise differences
$a-b$ ($a \ne b$) of $S$ and test distinctness, i.e.\ check whether
$|S|(|S|-1)$ equals the number of distinct nonzero differences. Complexity
$O(|S|^2)$.

\medskip
\noindent\textbf{Algorithm B (Greedy Sidon extension).} Scan $x = 1, \dots, N$,
maintaining the set $D$ of realized differences; admit $x$ iff no $x - s$
(over chosen $s$) lies in $D$, then update $D$. Complexity $O(N\,|S|)$. This
yields the classical Mian--Chowla-type sequence.

\section{Applications}
Sidon sets provide distinct-baseline layouts for radar and antenna arrays
(maximizing angular resolution), low-autocorrelation sequences for
error-correcting and spread-spectrum codes, and --- through the
convolution-kernel bound --- a direct analogue of filter design in signal
processing and machine learning.

\section{Discussion and future work}
The difference-set method extracts the entire leading-order upper bound from a
single injectivity observation, yet is honest about its structural saturation
at constant $\sqrt{2}$; surpassing it needs windowed averaging. The
powers-of-two family shows how little technology proves non-degeneracy.
Concrete future directions include the sharp two-term elementary bound $F(N)
\le N^{1/2} + N^{1/4} + 1$, verification of the quadratic frontier
construction, an explicit linear-programming characterization of $\gamma_0
\approx 0.94601$, and additive-energy stability of the Sidon property.

