from typing import List

def quadratic_sidon(p: int) -> List[int]:
    """Quadratic Sidon construction Q_p = {2p*i + (i^2 mod p) : 0 <= i < p},
    living inside {1, ..., 2p^2}. For prime p this attains order sqrt(N).
    Runs in O(p) time."""
    return [2 * p * i + (i * i) % p for i in range(p)]

from itertools import combinations
from typing import List, Set

def is_sidon(s: List[int]) -> bool:
    """Verify the Sidon property by testing distinctness of pairwise differences.
    Runs in O(|s|^2) time and space."""
    diffs: Set[int] = set()
    for a, b in combinations(s, 2):
        d = a - b
        if d in diffs or -d in diffs:
            return False
        diffs.add(d); diffs.add(-d)
    return True

if __name__ == "__main__":
    for k in range(1, 9):
        s = [2 ** i for i in range(k)]
        diffs = {a - b for a in s for b in s if a != b}
        print(f"k={k}: {s} Sidon={is_sidon(s)} pairs={k*(k-1)} distinct={len(diffs)}")

